// Special flow for Bukhara/Pravda kitchen receipt.
(function(){
 state.kitchenSupplyDishes=[];state.kitchenSupplyQty={};state.kitchenSupplySearch='';state.kitchenSupplyBusy=false;state.kitchenSupplyLoadedFor='';state.kitchenSupplySelected=null;
 function currentBusinessDate(){try{return state.home?.businessDate||businessDate()||''}catch{return state.home?.businessDate||''}}
 function cfg(){if(state.point==='BUKHARA')return {source:'Бухара Кухня',target:'Бухара раздача',transfer:true,test:true};if(state.point==='PRAVDA'){const after=currentBusinessDate()>='2026-09-25';return after?{source:'Правда Кухня',target:'Правда раздача',transfer:true}:{source:'Правда Кухня',target:'Правда Кухня',transfer:false};}return null}
 function employeeActor(){return localStorage.getItem('stolovaya:employee-name')||sessionStorage.getItem('stolovaya:employee-name')||'Буфетчик'}
 const baseHome=homeScreen;homeScreen=function(){let html=baseHome();const c=cfg();if(!c)return html;return html.replace(/<button data-screen="transfer"[^>]*>[\s\S]*?<\/button>/,`<button type="button" id="kitchen-supply-open" ${state.home?.submitted||state.home?.dayClosed?'disabled':''}><span>⇩</span><div><b>Получить с кухни</b></div></button>`)};
 async function openKitchenSupply(){const c=cfg();if(!c||state.home?.submitted||state.home?.dayClosed)return;state.screen='kitchen-supply';state.message='';render();if(state.kitchenSupplyLoadedFor===state.point&&state.kitchenSupplyDishes.length)return;state.kitchenSupplyBusy=true;render();try{state.kitchenSupplyDishes=await rpc('public_kitchen_supply_dishes',{p_token:state.token,p_point_code:state.point});state.kitchenSupplyLoadedFor=state.point}catch(e){state.message=e.message||'Не удалось загрузить блюда'}finally{state.kitchenSupplyBusy=false;render()}}
 function matches(){const q=state.kitchenSupplySearch.trim().toLowerCase();if(q.length<2)return[];return(state.kitchenSupplyDishes||[]).filter(x=>clean(x.name).toLowerCase().includes(q)||String(x.code||'').toLowerCase().includes(q)).slice(0,12)}
 function selectedRows(){return(state.kitchenSupplyDishes||[]).filter(x=>n(state.kitchenSupplyQty[x.dishId])>0)}
 function kitchenSupplyScreen(){const c=cfg();if(!c)return `${header()}${back('Получить с кухни')}<div class="notice">Эта операция доступна только на Бухаре и Правде.</div>`;const found=matches(),chosen=selectedRows();const hint=c.test?'Можно получать с кухни несколько раз за день. Каждое новое получение <b>добавится в одно общее перемещение Бухара Кухня → Бухара раздача</b>. Акт приготовления сформируем по итогам закрытия дня.':'';return `${header()}${back('Получить с кухни')}<section class="question-card kitchen-source"><h2>${esc(c.source)} → ${esc(c.target)}</h2><p>${hint}</p></section><div class="kitchen-picker"><input id="kitchen-supply-search" class="search" autocomplete="off" placeholder="Начните вводить название блюда" value="${esc(state.kitchenSupplySearch)}">${state.kitchenSupplySearch.trim().length>=2?`<div class="kitchen-suggestions">${found.length?found.map(x=>`<button type="button" data-kitchen-pick="${x.dishId}"><b>${esc(clean(x.name))}</b><small>${esc(x.group||'Прочее')}${x.code?` · ${esc(x.code)}`:''}</small></button>`).join(''):'<div class="kitchen-no-match">Ничего не найдено</div>'}</div>`:''}</div>${chosen.length?`<div class="simple-cards kitchen-supply-list">${chosen.map(x=>`<article><div><b>${esc(clean(x.name))}</b><small>${esc(x.group||'Прочее')}${x.code?` · ${esc(x.code)}`:''}</small></div><div class="kitchen-qty"><input data-kitchen-supply="${x.dishId}" inputmode="decimal" value="${esc(state.kitchenSupplyQty[x.dishId])}"><button type="button" data-kitchen-remove="${x.dishId}">×</button></div></article>`).join('')}</div>`:'<div class="notice">Введите минимум 2 буквы и выберите блюдо из списка.</div>'}<div class="sticky-action"><button id="kitchen-supply-send" class="primary" ${state.kitchenSupplyBusy||!chosen.length?'disabled':''}>${state.kitchenSupplyBusy?'Проводим…':`Добавить к получению${chosen.length?` · ${chosen.length}`:''}`}</button></div>${state.message?`<p class="toast">${esc(state.message)}</p>`:''}`}
 async function sendKitchenSupply(){if(state.kitchenSupplyBusy)return;const items=selectedRows().map(x=>({dishId:x.dishId,quantity:n(state.kitchenSupplyQty[x.dishId])}));if(!items.length)return;if(!confirm(`Добавить получение с кухни?\nПозиций: ${items.length}`))return;state.kitchenSupplyBusy=true;state.message='';render();try{const r=await rpc('public_receive_from_kitchen',{p_token:state.token,p_point_code:state.point,p_items:items,p_actor:employeeActor(),p_business_date:businessDate()});state.kitchenSupplyQty={};state.kitchenSupplySearch='';await loadPoint();state.screen='home';state.message=r.accumulated?`Получение добавлено в общее перемещение ${r.transferDocument}.`:'Получение проведено.'}catch(e){state.message=e.message||'Не удалось провести получение'}finally{state.kitchenSupplyBusy=false;render()}}
 const baseRender=render;render=function(){if(state.screen==='kitchen-supply'){app.innerHTML=kitchenSupplyScreen();bind();setTimeout(()=>{const s=document.getElementById('kitchen-supply-search');if(s&&state.kitchenSupplySearch)s.focus()},0);return}baseRender()};
 const baseBind=bind;bind=function(){baseBind();document.getElementById('kitchen-supply-open')?.addEventListener('click',openKitchenSupply);const search=document.getElementById('kitchen-supply-search');if(search)search.oninput=e=>{state.kitchenSupplySearch=e.target.value;render()};document.querySelectorAll('[data-kitchen-pick]').forEach(b=>b.onclick=()=>{const id=b.dataset.kitchenPick;if(!state.kitchenSupplyQty[id])state.kitchenSupplyQty[id]='1';state.kitchenSupplySearch='';render()});document.querySelectorAll('[data-kitchen-remove]').forEach(b=>b.onclick=()=>{delete state.kitchenSupplyQty[b.dataset.kitchenRemove];render()});document.querySelectorAll('[data-kitchen-supply]').forEach(inp=>inp.oninput=e=>{const v=e.target.value.replace(',','.');if(v&&!/^\d*(\.\d{0,3})?$/.test(v))return;state.kitchenSupplyQty[inp.dataset.kitchenSupply]=v});document.getElementById('kitchen-supply-send')?.addEventListener('click',sendKitchenSupply)};
 const style=document.createElement('style');style.textContent=`.kitchen-source{margin-bottom:12px}.kitchen-source h2{margin-bottom:6px}.kitchen-picker{position:relative;margin-bottom:12px}.kitchen-suggestions{margin-top:-8px;background:#fff;border:1px solid #d8ddd9;border-radius:0 0 14px 14px;box-shadow:0 8px 24px #0002;max-height:52vh;overflow:auto;position:relative;z-index:20}.kitchen-suggestions button{display:flex;flex-direction:column;width:100%;text-align:left;padding:12px 14px;border:0;border-bottom:1px solid #eef0ee;background:#fff}.kitchen-suggestions button:last-child{border-bottom:0}.kitchen-suggestions small{margin-top:3px;color:#68716b}.kitchen-no-match{padding:14px;color:#68716b}.kitchen-qty{display:flex;align-items:center;gap:6px}.kitchen-qty input{max-width:82px}.kitchen-qty button{width:34px;height:34px;border:0;border-radius:50%;font-size:22px}`;document.head.appendChild(style);
})();